var wallet = new Wallet(100);
wallet.Deposit(20);
wallet.Withdraw(50);
Console.WriteLine($"balance:{wallet.Balance}");
try { wallet.Withdraw(100); } catch (InvalidOperationException) { Console.WriteLine("insufficient"); }
try { wallet.Deposit(0); } catch (ArgumentOutOfRangeException) { Console.WriteLine("invalid amount"); }
try { _ = new Wallet(-1); } catch (ArgumentOutOfRangeException) { Console.WriteLine("invalid initial"); }
var full = new Wallet(int.MaxValue);
try { full.Deposit(1); } catch (OverflowException) { Console.WriteLine("overflow"); }
Console.WriteLine($"unchanged:{wallet.Balance}/{full.Balance}");
sealed class Wallet
{
    public int Balance { get; private set; }
    public Wallet(int initial) { if (initial < 0) throw new ArgumentOutOfRangeException(nameof(initial)); Balance = initial; }
    public void Deposit(int amount) { Positive(amount); int next = checked(Balance + amount); Balance = next; }
    public void Withdraw(int amount) { Positive(amount); if (amount > Balance) throw new InvalidOperationException("Insufficient points"); Balance -= amount; }
    static void Positive(int amount) { if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount)); }
}

