    public IReadOnlyList<string> Items => items;
}
sealed record Product(string Name);
sealed class Catalog
{
    private readonly List<Product> items = new() { new Product("A") };
    public void Add(string name) { if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException(nameof(name)); items.Add(new Product(name)); }
    public Product[] Snapshot() => items.ToArray();
}

