var order = new Order();
Console.WriteLine($"empty:{order.TryConfirm()}/{order.State}");
order.Add(2, 30);
Console.WriteLine($"confirm:{order.TryConfirm()}/{order.State}/{order.Total}");
try { order.Add(1, 10); } catch (InvalidOperationException) { Console.WriteLine("locked"); }
Console.WriteLine($"final:{order.State}/{order.Total}");
enum OrderState { Draft, Confirmed }
sealed class Order
{
    public OrderState State { get; private set; }
    public int Total { get; private set; }
    private int count;
    public void Add(int quantity, int unitPoints)
    {
        if (State != OrderState.Draft) throw new InvalidOperationException("Only draft can change");
        if (quantity <= 0 || unitPoints <= 0) throw new ArgumentOutOfRangeException();
        int nextTotal = checked(Total + checked(quantity * unitPoints));
        int nextCount = checked(count + quantity);
        Total = nextTotal; count = nextCount;
    }
    public bool TryConfirm() { if (State != OrderState.Draft || count == 0) return false; State = OrderState.Confirmed; return true; }
}

